tinymce.PluginManager.add('filemanager', function(editor) {

	// Register options for TinyMCE 6/7+ Options API
	if (editor.options && typeof editor.options.register === 'function') {
		editor.options.register('external_filemanager_path', { processor: 'string', default: '' });
		editor.options.register('filemanager_title', { processor: 'string', default: 'RESPONSIVE FileManager' });
		editor.options.register('filemanager_access_key', { processor: 'string', default: 'key' });
		editor.options.register('filemanager_sort_by', { processor: 'string', default: '' });
		editor.options.register('filemanager_descending', { processor: 'number', default: 0 });
		editor.options.register('filemanager_subfolder', { processor: 'string', default: '' });
		editor.options.register('filemanager_crossdomain', { processor: 'number', default: 0 });
	}

	function getOption(name) {
		if (editor.options && typeof editor.options.get === 'function') {
			return editor.options.get(name);
		}
		if (editor.settings && typeof editor.settings[name] !== 'undefined') {
			return editor.settings[name];
		}
		return undefined;
	}

	// Set file picker callback and types
	if (editor.options && typeof editor.options.set === 'function') {
		editor.options.set('file_picker_types', 'file image media');
		editor.options.set('file_picker_callback', filemanager);
	} else if (editor.settings) {
		editor.settings.file_picker_types = 'file image media';
		editor.settings.file_picker_callback = filemanager;
	}

	function filemanager_onMessage(event){
		var externalPath = getOption('external_filemanager_path') || '';
		if(externalPath.toLowerCase().indexOf(event.origin.toLowerCase()) === 0){
			if(event.data && event.data.sender === 'responsivefilemanager'){
				if(editor.windowManager && typeof editor.windowManager.close === 'function') {
					editor.windowManager.close();
				}

				// Remove event listener for a message from ResponsiveFilemanager
				if(window.removeEventListener){
					window.removeEventListener('message', filemanager_onMessage, false);
				} else if (window.detachEvent) {
					window.detachEvent('onmessage', filemanager_onMessage);
				}
			}
		}
	}

	function filemanager(callback, value, meta) {
		var width = window.innerWidth-30;
		var height = window.innerHeight-60;
		if(width > 1800) width=1800;
		if(height > 1200) height=1200;
		if(width>600){
			var width_reduce = (width - 20) % 138;
			width = width - width_reduce + 10;
		}

		// DEFAULT AS FILE
		var urltype=2;
		if (meta.filetype === 'image' || meta.mediaType === 'image') { urltype=1; }
		if (meta.filetype === 'media' || meta.mediaType === 'media') { urltype=3; }

		var title="RESPONSIVE FileManager";
		var optTitle = getOption('filemanager_title');
		if (optTitle) {
			title=optTitle;
		}
		var akey="key";
		var optAkey = getOption('filemanager_access_key');
		if (optAkey) {
			akey=optAkey;
		}
		var sort_by="";
		var optSortBy = getOption('filemanager_sort_by');
		if (optSortBy) {
			sort_by="&sort_by="+optSortBy;
		}
		var descending=0;
		var optDesc = getOption('filemanager_descending');
		if (optDesc) {
			descending=optDesc;
		}
		var fldr="";
		var optFldr = getOption('filemanager_subfolder');
		if (optFldr) {
			fldr="&fldr="+optFldr;
		}
		var crossdomain="";
		var optCrossdomain = getOption('filemanager_crossdomain');
		if (optCrossdomain) {
			crossdomain="&crossdomain=1";

			// Add handler for a message from ResponsiveFilemanager
			if(window.addEventListener){
				window.addEventListener('message', filemanager_onMessage, false);
			} else if (window.detachEvent) {
				window.attachEvent('onmessage', filemanager_onMessage);
			}
		}

		window.addEventListener('message', function receiveMessage(event) {
			if (event && event.data && event.data.sender === 'responsivefilemanager' && typeof event.data.url !== 'undefined') {
				window.removeEventListener('message', receiveMessage, false);
				callback(event.data.url);
			}
		}, false);

		var externalPath = getOption('external_filemanager_path') || '';
		var language = getOption('language') || 'fr_FR';
		var dialogUrl = externalPath+'dialog.php?type='+urltype+'&descending='+descending+sort_by+fldr+crossdomain+'&lang='+language+'&akey='+akey;

		if (tinymce.majorVersion >= 5) {
			editor.windowManager.openUrl({
				title: title,
				url: dialogUrl,
				width: width,
				height: height,
				resizable: true,
				maximizable: true,
				inline: 1
			});
		} else {
			editor.windowManager.open({
				title: title,
				file: dialogUrl,
				width: width,
				height: height,
				resizable: true,
				maximizable: true,
				inline: 1
			});
		}
	}

	return false;
});
